/* ECMWF forecast web map — Leaflet + ECMWF ecCharts WMS + point meteogram.
 * Generated by the ecmwf-weather agent skills. Reads config.json (written by webmap.py create).
 * Data: © ECMWF, CC BY 4.0. Layers named composition_* are Copernicus (CAMS) products. */

// ---- time helpers (also unit-tested with node) ----------------------------------------------
function fmtISO(d) { return d.toISOString().replace('.000Z', 'Z'); }

function parseDuration(p) {
  const m = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?)?$/.exec(p);
  if (!m) throw new Error('unsupported period ' + p);
  return ((+(m[1] || 0) * 24 + +(m[2] || 0)) * 60 + +(m[3] || 0)) * 60000;
}

/** Expand a WMS time dimension ("t1,t2/t3/PT6H,...") into sorted ISO strings. */
function expandTime(text) {
  const out = new Set();
  for (const part of text.split(',').map(s => s.trim()).filter(Boolean)) {
    if (part.includes('/')) {
      const [a, b, p] = part.split('/');
      const end = new Date(b).getTime(), dt = parseDuration(p);
      for (let t = new Date(a).getTime(); t <= end; t += dt) out.add(fmtISO(new Date(t)));
    } else out.add(part);
  }
  return [...out].sort();
}

function closestTime(times, date) {
  let best = times[0], bestDiff = Infinity;
  for (const t of times) {
    const d = Math.abs(new Date(t) - date);
    if (d < bestDiff) { best = t; bestDiff = d; }
  }
  return best;
}

// ---- value formatting ------------------------------------------------------------------------
function niceValue(v, unit) {
  if (unit === 'K') return (v - 273.15).toFixed(1) + ' °C';
  if (unit === 'Pa') return (v / 100).toFixed(1) + ' hPa';
  return (+v).toFixed(1) + ' ' + (unit || '');
}

// ---- app -------------------------------------------------------------------------------------
async function init() {
  const cfg = await (await fetch('config.json')).json();
  const base = cfg.wms + '?token=' + encodeURIComponent(cfg.token);
  const $ = id => document.getElementById(id);

  const map = L.map('map', { worldCopyJump: true }).setView(cfg.center, cfg.zoom);
  const wmsOpts = { format: 'image/png', version: '1.3.0', styles: '' };
  L.tileLayer.wms(base, { ...wmsOpts, layers: 'background', transparent: false }).addTo(map);
  const data = L.tileLayer.wms(base, { ...wmsOpts, layers: cfg.layers[0], transparent: true, opacity: 0.85 }).addTo(map);
  L.tileLayer.wms(base, { ...wmsOpts, layers: 'foreground', transparent: true, zIndex: 10 }).addTo(map);

  const year = new Date().getUTCFullYear();
  const credit = `Forecast data &amp; maps: © ${year} <a href="https://www.ecmwf.int">ECMWF</a>, ` +
    '<a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>';
  map.attributionControl.addAttribution(credit);
  $('attribution').innerHTML = credit + '. ECMWF accepts no liability for errors or omissions.';

  // Capabilities: titles, times, legends for the configured layers.
  const xml = new DOMParser().parseFromString(
    await (await fetch(base + '&service=WMS&version=1.3.0&request=GetCapabilities')).text(), 'text/xml');
  const info = {};
  for (const el of xml.getElementsByTagName('Layer')) {
    const name = el.getElementsByTagName('Name')[0]?.textContent;
    if (!cfg.layers.includes(name) || info[name]) continue;
    const dim = [...el.getElementsByTagName('Dimension')].find(d => d.getAttribute('name') === 'time');
    const legend = el.getElementsByTagName('OnlineResource')[0];
    info[name] = {
      title: el.getElementsByTagName('Title')[0]?.textContent || name,
      times: dim ? expandTime(dim.textContent) : [],
      default: dim?.getAttribute('default'),
      legend: legend?.getAttribute('xlink:href') || legend?.getAttributeNS('http://www.w3.org/1999/xlink', 'href'),
    };
  }
  for (const name of cfg.layers) {
    if (!info[name]) continue;
    $('layer').add(new Option(info[name].title, name));
  }

  let current = cfg.layers.find(n => info[n]);
  let times = [];
  const setTime = i => {
    $('time').value = i;
    const t = times[i];
    $('time-label').textContent = t ? t.replace('T', ' ').replace(':00:00Z', ' UTC') : 'static';
    if (t) data.setParams({ time: t });
  };
  const selectLayer = name => {
    current = name;
    times = info[name].times;
    data.setParams({ layers: name, time: undefined }, true);
    $('time').max = Math.max(times.length - 1, 0);
    $('legend').src = info[name].legend || '';
    setTime(Math.max(times.indexOf(closestTime(times, new Date())), 0));
    if (name.startsWith('composition_')) $('attribution').innerHTML +=
      ' Generated using Copernicus Atmosphere Monitoring Service information.';
  };
  $('layer').onchange = e => selectLayer(e.target.value);
  $('time').oninput = e => setTime(+e.target.value);
  $('prev').onclick = () => setTime(Math.max(+$('time').value - 1, 0));
  $('next').onclick = () => setTime(Math.min(+$('time').value + 1, times.length - 1));
  let timer = null;
  $('play').onclick = () => {
    if (timer) { clearInterval(timer); timer = null; $('play').textContent = '▶ Play'; return; }
    $('play').textContent = '❚❚ Pause';
    timer = setInterval(() => setTime((+$('time').value + 1) % times.length), 1200);
  };
  if (current) selectLayer(current);

  // Click: value of the current layer (GetFeatureInfo) + meteogram from the local server.
  let marker = null;
  map.on('click', async e => {
    const { lat, lng } = e.latlng, lon = ((lng + 540) % 360) - 180;
    marker = marker ? marker.setLatLng(e.latlng) : L.marker(e.latlng).addTo(map);
    $('point').textContent = `${lat.toFixed(2)}, ${lon.toFixed(2)}: …`;
    const d = 0.01, t = times[+$('time').value];
    const q = new URLSearchParams({ service: 'WMS', version: '1.3.0', request: 'GetFeatureInfo',
      layers: current, query_layers: current, styles: '', crs: 'EPSG:4326',
      bbox: [lat - d, lon - d, lat + d, lon + d].join(','), width: 3, height: 3, i: 1, j: 1,
      info_format: 'application/json', ...(t ? { time: t } : {}) });
    try {
      const probe = (await (await fetch(base + '&' + q)).json()).Probes?.[0];
      $('point').textContent = `${lat.toFixed(2)}, ${lon.toFixed(2)} — ${info[current].title}: ` +
        niceValue(probe.Value.Data, probe.Value.Unit);
    } catch { $('point').textContent = `${lat.toFixed(2)}, ${lon.toFixed(2)}`; }

    const img = $('meteogram');
    if (!location.protocol.startsWith('http')) {
      img.hidden = true;
      $('point').textContent += ' — meteograms need the local server: uv run webmap.py serve <folder>';
      return;
    }
    img.hidden = true;  // don't show the previous point's meteogram while loading
    const status = document.createElement('div');
    status.textContent = 'Meteogram: fetching ECMWF Open Data (first click ~1 min, then ~20 s)…';
    $('point').appendChild(status);
    img.onload = () => { img.hidden = false; status.remove(); };
    img.alt = `ECMWF meteogram for ${lat.toFixed(2)}, ${lon.toFixed(2)}`;
    img.src = `api/meteogram.png?lat=${lat.toFixed(3)}&lon=${lon.toFixed(3)}`;
    img.onerror = async () => {
      img.hidden = true;
      const r = await fetch(img.src).catch(() => null);
      $('point').textContent += ' — meteogram failed: ' + (r ? await r.text() : 'server not reachable');
    };
  });
}

if (typeof window !== 'undefined' && typeof document !== 'undefined') {
  window.addEventListener('DOMContentLoaded', () => init().catch(err => {
    document.getElementById('point').textContent = 'Failed to load: ' + err;
  }));
}
